/**
 * How the clients of release 2.0.0-beta.15, published from main at f5f3256ab, read public app
 * listings and app source, frozen. Installed CLIs, desktop apps and local servers of that release keep
 * calling Cloud: its local servers read the public registry, and its CLI reads app source. They
 * state no wire revision, so a host must answer them in the format these schemas decode.
 *
 * Do not edit this file. Snapshot a later release in a new file named for its commit. Copied with
 * effect 4.0.1 (bun.lock at f5f3256ab) from these sources, by `git rev-parse f5f3256ab:<path>`:
 * - e748356672dc75b6c62c1025382c0a58fa3171fe packages/sdk/src/contracts/registry.ts
 * - a04d181ca75701db0a2645724800d7258d29ec82 packages/sdk/src/contracts/source.ts
 * - 94b650294b9c120ff05153f5c993fb76dd237362 packages/sdk/src/contracts/shared.ts
 * - 912f8bb524cd891b7eb3ac04b9b228df67e3d016 packages/app-management/src/contracts/api.ts
 * - 8ce4b56add20091c8a727cebd0aac2060d7ad95f packages/sdk/src/implementation/remote-registry.ts
 * - 104307e77b7625cacb05e8dfb8af93ae79c3c908 packages/sdk/src/implementation/registry.ts
 * - bc4573a29e5567bd991aa3ab6e9f1b70d85cc41c packages/app-management/src/cli.ts
 * - 172fb330e11ec1db557bc7f824dcf440d7e34519 packages/app-management/src/client-error.ts
 * The release's `Release 2.0.0-beta.15` commit, 1a03f723f, is older than the published build.
 * The schemas run with this repository's effect, not 4.0.1, once it is upgraded.
 */
import { Effect, Schema } from "effect";

/** `PackageName` in packages/sdk/src/contracts/registry.ts. */
const PackageName = Schema.String.check(
  Schema.isPattern(/^@[a-z0-9][a-z0-9-]{0,79}\/[a-z0-9][a-z0-9-]{0,62}$/u),
);
/** `SourceCommit` in packages/sdk/src/contracts/source.ts. */
const SourceCommit = Schema.String.check(Schema.isPattern(/^[a-f0-9]{40}$/u));
/** `SourceFilePath` in packages/sdk/src/contracts/source.ts. */
const SourceFilePath = Schema.String.pipe(
  Schema.check(
    Schema.makeFilter((path: string) => {
      if (path.includes("\0")) return "expected no NUL bytes";
      if (path.includes("\\")) return "expected POSIX separators";
      if (path.startsWith("/")) return "expected a relative path";
      return path.length > 0 && path.split("/").every((s) => s !== "" && s !== "." && s !== "..")
        ? true
        : "expected canonical segments (non-empty, no `.` or `..`)";
    }),
  ),
);
const publicSourcePrefix = "ui/public/";
/** `SourceFile` and its members in packages/sdk/src/contracts/source.ts. */
const SourceTextFile = Schema.Struct({ path: SourceFilePath, content: Schema.String });
const SourceBinaryFile = Schema.Struct({
  path: SourceFilePath,
  content: Schema.String.check(
    Schema.isPattern(/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/u),
  ),
  encoding: Schema.Literal("base64"),
});
const SourceStoredFile = Schema.Struct({
  path: SourceFilePath,
  object: Schema.String.check(Schema.isPattern(/^[a-f0-9]{40}$/u)),
  size: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
});
const SourceFile = Schema.Union([SourceBinaryFile, SourceStoredFile, SourceTextFile]);
type SourceFile = typeof SourceFile.Type;
const isTextFile = (file: SourceFile): file is typeof SourceTextFile.Type =>
  !("object" in file) && !("encoding" in file);
/** `SourceFiles` in packages/sdk/src/contracts/source.ts. */
const SourceFiles = Schema.NonEmptyArray(SourceFile).pipe(
  Schema.check(
    Schema.makeFilter((files: ReadonlyArray<SourceFile>) =>
      new Set(files.map((f) => f.path)).size === files.length ? true : "expected unique paths",
    ),
    Schema.makeFilter((files: ReadonlyArray<SourceFile>) =>
      files.some((f) => f.path === "index.ts") ? true : "expected a root index.ts",
    ),
    Schema.makeFilter((files: ReadonlyArray<SourceFile>) => {
      const misplaced = files.find(
        (file) => !isTextFile(file) && !file.path.startsWith(publicSourcePrefix),
      );
      return misplaced === undefined
        ? true
        : `expected ${misplaced.path} to be UTF-8 text: only files under ${publicSourcePrefix} may be binary or stored`;
    }),
  ),
);
/** `AppCodeId` in packages/sdk/src/contracts/shared.ts. */
const AppCodeId = Schema.String.check(Schema.isPattern(/^code_[\s\S]+$/u));
/** `SourceSnapshot` in packages/sdk/src/contracts/source.ts. */
const SourceSnapshot = Schema.Struct({
  revision: Schema.Struct({ code: AppCodeId, commit: SourceCommit }),
  files: SourceFiles,
});
/** `PackageManifest` in packages/sdk/src/contracts/registry.ts. */
const PackageManifest = Schema.Struct({
  name: PackageName,
  description: Schema.optional(Schema.String.check(Schema.isMaxLength(2000))),
});
/** `PublicationIssue` in packages/sdk/src/contracts/registry.ts. */
const PublicationIssue = Schema.Struct({
  _tag: Schema.Literal("PublicationIssue"),
  reason: Schema.Literals([
    "missing-manifest",
    "invalid-json",
    "missing-name",
    "unscoped-name",
    "invalid-name",
    "invalid-metadata",
    "invalid-source",
    "limit",
    "forbidden-scope",
    "name-taken",
  ]),
  name: Schema.NullOr(Schema.String),
});
/** `PublicationReadiness` in packages/sdk/src/contracts/registry.ts. */
const PublicationReadiness = Schema.Union([
  Schema.Struct({ status: Schema.Literal("ready"), manifest: PackageManifest }),
  Schema.Struct({
    status: Schema.Literal("blocked"),
    issue: PublicationIssue,
    suggestedName: Schema.NullOr(PackageName),
  }),
]);
/** `Publication` and `PublicationSnapshot` in packages/sdk/src/contracts/registry.ts. */
const Publication = Schema.Struct({
  name: PackageName,
  commit: SourceCommit,
  description: Schema.String,
  publishedAt: Schema.String,
});
const PublicationSnapshot = Schema.Struct({ publication: Publication, files: SourceFiles });
/** `AppSourceView` in packages/app-management/src/contracts/api.ts. */
const AppSourceView = Schema.Struct({
  ...SourceSnapshot.fields,
  namespace: Schema.NullOr(Schema.String),
  gitPath: Schema.String,
  gitUrl: Schema.String,
  canEdit: Schema.Boolean,
  publication: Schema.NullOr(PublicationReadiness),
});

/**
 * What that release's local server answers for the whole public catalog: the listings, or the
 * failure its `remoteRegistry` maps any undecodable list to (`read` in remote-registry.ts).
 */
export const releasedCatalog = (body: unknown) =>
  Schema.decodeUnknownEffect(Schema.Array(Publication))(body).pipe(
    Effect.mapError(() => ({ _tag: "RegistryError", reason: "invalid-source" }) as const),
  );

/**
 * What that release's local server makes of a listing's source when it copies `name` at `commit`:
 * `snapshot` in remote-registry.ts, then `resolvePublication` in registry.ts, which requires the
 * source's package.json to name the listing exactly.
 */
export const releasedInstall = (body: unknown, name: string, commit: string) =>
  Effect.gen(function* () {
    const snapshot = yield* Schema.decodeUnknownEffect(PublicationSnapshot)(body).pipe(
      Effect.mapError(() => "invalid-source" as const),
    );
    if (snapshot.publication.name !== name || snapshot.publication.commit !== commit)
      return yield* Effect.fail("changed" as const);
    const manifest = snapshot.files.find((file) => file.path === "package.json");
    if (manifest === undefined || !isTextFile(manifest))
      return yield* Effect.fail("invalid-manifest" as const);
    const document = yield* Schema.decodeUnknownEffect(
      Schema.fromJsonString(Schema.Struct({ name: Schema.Unknown })),
    )(manifest.content).pipe(Effect.mapError(() => "invalid-manifest" as const));
    if (!Schema.is(PackageName)(document.name)) return yield* Effect.fail("invalid-manifest");
    if (document.name !== name) return yield* Effect.fail("invalid-source" as const);
    return snapshot.files.length;
  });

/**
 * What that release's CLI makes of the app source it reads (`workingSource` in cli.ts): for
 * `apps source`, `apps deploy --files`, and `apps create` with public files after it creates the
 * app. The decoded view, or `UnexpectedResponse` when the body does not decode (`hostFailure` and
 * `hostRequestFailure` in cli.ts).
 */
export const releasedSourceView = (body: unknown) =>
  Schema.decodeUnknownEffect(AppSourceView)(body).pipe(
    Effect.mapError(() => "UnexpectedResponse" as const),
  );

/** The tags of `appOperationErrors` in packages/app-management/src/contracts/api.ts. */
const declaredErrors = new Set([
  "StorageError",
  "SourceError",
  "RegistryError",
  "AppAccessDenied",
  "AppNotFound",
  "AppNotDeployed",
  "DeploymentNotFound",
  "AppNameTaken",
  "AppSlugTaken",
  "AppDeploymentChanged",
  "AccountNotFound",
  "AccountSelectionInvalid",
  "DeploymentBuildFailed",
  "BuildMemoryExceeded",
]);
/** `HostRecovery` in packages/app-management/src/client-error.ts. */
const HostRecovery = Schema.Struct({ action: Schema.String, instructions: Schema.String });
/** `HostAnswer` in packages/app-management/src/cli.ts, after its JSON parse. */
const HostAnswer = Schema.Struct({
  _tag: Schema.NonEmptyString.check(Schema.isMaxLength(128)),
  message: Schema.NonEmptyString.check(Schema.isMaxLength(4096)),
  recovery: Schema.optional(HostRecovery),
});

/**
 * What that release's CLI prints when an app management request fails with an error its contract
 * does not declare (`hostFailure`, `hostAnswer` and `hostRequestFailure` in cli.ts): the host's own
 * code, status, message and recovery. A declared error, or a body that is not an Executor error,
 * never reaches this path, so it fails here.
 */
export const releasedHostAnswer = (status: number, body: unknown) =>
  Schema.decodeUnknownEffect(HostAnswer)(body).pipe(
    Effect.mapError(() => "UnexpectedResponse" as const),
    Effect.filterOrFail(
      (answer) => !declaredErrors.has(answer._tag),
      () => "declared" as const,
    ),
    Effect.map(({ _tag, message, recovery }) => ({
      code: _tag,
      status,
      message,
      ...(recovery === undefined ? {} : { recovery }),
    })),
  );
